      ctx.fillStyle = tv < 1.2 ? "#ef4444" : "#fbbf24";
      ctx.strokeStyle = "rgba(0,0,0,.6)"; ctx.lineWidth = 3;
      const txt = tv.toFixed(1);
      ctx.strokeText(txt, 0, -24); ctx.fillText(txt, 0, -24);
